b:if.script:
//
{
  "@context": "https://schema.org",
  "@type": "NewsArticle",
  "headline": "<data:post.title.escaped/>",
  "description": "<data:post.snippet.escaped/>",
  "url": "<data:post.url.canonical/>",
  "datePublished": "<data:post.date.iso8601/>",
  "dateModified": "<data:post.lastUpdated.iso8601 ?: data:post.date.iso8601/>",
  "author": {
    "@type": "Person",
    "@id": "https://cyberdudebivash.com/#person",
    "name": "CyberDudeBivash",
    "url": "https://cyberdudebivash.com"
  },
  "publisher": {
    "@type": "Organization",
    "@id": "https://cyberdudebivash.com/#organization",
    "name": "CYBERDUDEBIVASH® — Sentinel APEX",
    "logo": {
      "@type": "ImageObject",
      "url": "https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjHxielQRwqtcqGJksMR6mYVuBszBssm8rs5zPQIcCauKNqz6V3pf3dhLnW4o0ufISQ_q5VNCBMEktbxFymEIKpFxG01uPMOxFEEQRtoWMK-E3yKSF3uZKa7eXsi-iSgddkEtxPLvIHCkYLkZFnIwcLqqhUgKELhT-XXrF__c4skHmpzKb_HavNkPnxBaI/w1200-h630/CYBERDUDEBIVASH-LOGO.png",
      "width": 1200,
      "height": 630
    }
  },
  "image": {
    "@type": "ImageObject",
    "url": "<b:if cond='data:post.firstImageUrl'>data:post.firstImageUrl<b:else/>https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjHxielQRwqtcqGJksMR6mYVuBszBssm8rs5zPQIcCauKNqz6V3pf3dhLnW4o0ufISQ_q5VNCBMEktbxFymEIKpFxG01uPMOxFEEQRtoWMK-E3yKSF3uZKa7eXsi-iSgddkEtxPLvIHCkYLkZFnIwcLqqhUgKELhT-XXrF__c4skHmpzKb_HavNkPnxBaI/w1200-h630/CYBERDUDEBIVASH-LOGO.png</b:if>",
    "width": 1200,
    "height": 630
  },
  "mainEntityOfPage": {
    "@type": "WebPage",
    "@id": "<data:post.url.canonical/>"
  },
  "articleSection": "Cybersecurity",
  "inLanguage": "en-US",
  "isAccessibleForFree": true,
  "keywords": "<b:loop values='data:post.labels' var='label'><data:label.name/><b:if cond='data:label != data:post.labels.last'>, </b:if></b:loop>"
}
//

body.script:
//

/* ── Reading Progress Bar ── */
(function(){
  var bar=document.getElementById('reading-progress');
  if(!bar)return;
  window.addEventListener('scroll',function(){
    var s=document.documentElement.scrollTop||document.body.scrollTop;
    var h=document.documentElement.scrollHeight-document.documentElement.clientHeight;
    bar.style.width=(h>0?Math.min(100,(s/h)*100):0)+'%';
  },{passive:true});
})();

/* ── Mobile Menu ── */
function toggleMobileMenu(btn){
  var m=document.getElementById('mobile-menu');
  if(!m)return;
  var open=m.classList.toggle('open');
  btn.classList.toggle('open',open);
  btn.setAttribute('aria-expanded',open);
}

/* ── Intel Timestamp ── */
(function(){
  var el=document.getElementById('intel-timestamp');
  if(el){el.textContent=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+'  UTC';}
  var tu=document.getElementById('threat-update-time');
  if(tu){tu.textContent=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';}
})();

/* ── Read Time Estimator ── */
(function(){
  var d=document.getElementById('read-time-display');
  if(!d)return;
  var body=document.querySelector('.post-body');
  if(!body)return;
  var words=(body.textContent||'').trim().split(/\s+/).length;
  var mins=Math.max(1,Math.round(words/200));
  d.textContent='⏱ '+mins+' min read';
})();

/* ── Lazy Load Images ── */
(function(){
  if('loading' in HTMLImageElement.prototype){
    document.querySelectorAll('img').forEach(function(img){
      if(!img.hasAttribute('loading'))img.setAttribute('loading','lazy');
    });
  }else if('IntersectionObserver' in window){
    var obs=new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){var img=e.target;if(img.dataset.src){img.src=img.dataset.src;}obs.unobserve(img);}
      });
    },{rootMargin:'200px'});
    document.querySelectorAll('img[data-src]').forEach(function(img){obs.observe(img);});
  }
})();

/* ── Smooth Anchor Scroll ── */
document.querySelectorAll('a[href^="#"]').forEach(function(a){
  a.addEventListener('click',function(e){
    var t=document.querySelector(this.getAttribute('href'));
    if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth',block:'start'});}
  });
});

/* ── AdSense Safety Init ── */
(window.adsbygoogle=window.adsbygoogle||[]);

//
